// New in this fork (awesome-claude): the desktop version of the pane, drawn with the shared kit.
import type { Elements, RenderElement } from 'claude-code'

import { ago } from '../kit/format'
import { C, FILE_TYPE, GLYPH, GRAY, TRACK } from '../kit/tokens'
import type { FileType } from '../kit/tokens'
import { EDGE, SPACE, kit } from '../kit/ui'

import type { Activity, FileTree } from '../types'
import { dirname, formatSize, HOST_ICON, hostKind, remoteName, type Row, underAny } from './tree'

/*
 * The desktop's file tree, as the other mods' desktop panes draw: a header line
 * with the folder and its actions as icons, the branch line, the search field,
 * then one row per file or folder (indent, fold arrow, Octicon, name, figures on
 * the right), and a footer with the selection and git activity.
 *
 * The rows are drawn here, not by the `Client` the terminal uses (rows.tsx): a
 * surface module can't draw `Svg`, and the rows' icons are Octicons. A press on
 * a row's name selects it and opens a folder, twice opens it, as a click does in
 * the terminal; Claude's reads and writes light their rows for as long as the
 * terminal's shimmer runs.
 */

export type DesktopElements = Pick<Elements['desktop'], 'Box' | 'Text' | 'Button' | 'Input' | 'Svg'>

/** What the desktop pane draws from, besides the tree itself. */
export type DesktopView = {
  t: FileTree
  rows: Row[]
  /** The git activity shown in the footer: the running one, else the latest. */
  latest: Activity | undefined
  /** Whether the tree follows the session's cwd (the home button lit). */
  follow: boolean
  now: number
  columns: number
  /** The pane's height in rows, so the footer sits on its bottom edge. */
  bodyRows: number
  /** A path relative to the tree's root, or shortened under home. */
  shown: (path: string) => string
  /** The id the branch line flashes under. */
  branchRow: string
}

/** What the pane's controls do; register.tsx runs them with its `$`. */
export type DesktopActions = {
  up: () => void
  home: () => void
  refresh: () => void
  hidden: () => void
  sizes: () => void
  collapse: () => void
  unselect: () => void
  press: (id: string) => void
  open: (id: string) => void
  search: (query: string) => void
  jump: (query: string) => void
}

/** The branch name's least width in cells, however many figures share its line. */
const HEAD_MIN = 6

/** An icon button's label: two Braille blanks, about the icon's two cells, drawn as nothing. */
export const BLANK = '⠀⠀'

/** The most rows drawn: a tree past it would outgrow what the desktop takes in one drawing. */
export const MAX_ROWS = 1500

const CODE = new Set(
  'ts tsx mts cts js jsx mjs cjs py rs go rb java kt kts swift c h cc cpp hpp cs php sh bash zsh fish lua sql html htm css scss sass less vue svelte zig ex exs erl hs ml scala dart r jl pl ps1 nix'.split(' '),
)

/** A file's Octicon: code for source files, a page for anything else. */
export const fileIcon = (name: string, kind: string, open: boolean) => {
  if (kind === 'dir') return open ? 'folder-open' : 'folder'
  const ext = name.includes('.') ? (name.split('.').pop() ?? '').toLowerCase() : ''
  return CODE.has(ext) ? 'file-code' : 'file'
}

/** Extensions by the file type IntelliJ's New UI draws them as (its `fileTypes` icons). */
const TYPE_BY_EXT = new Map<string, FileType>()
for (const [type, exts] of Object.entries({
  typescript: 'ts tsx mts cts',
  javascript: 'js jsx mjs cjs',
  json: 'json jsonc json5',
  markdown: 'md mdx markdown',
  yaml: 'yml yaml',
  config: 'toml ini cfg conf properties env editorconfig',
  style: 'css scss sass less',
  html: 'html htm xhtml',
  xml: 'xml xsd xsl plist',
  data: 'csv tsv',
  sql: 'sql',
  image: 'png jpg jpeg gif webp ico bmp svg avif',
  archive: 'zip tar gz tgz bz2 xz 7z rar jar',
} satisfies Partial<Record<FileType, string>>))
  for (const ext of exts.split(' ')) TYPE_BY_EXT.set(ext, type as FileType)

/** Names IntelliJ draws as config whatever their extension. */
const CONFIG_NAMES = new Set(['dockerfile', '.editorconfig', '.env', '.npmrc', '.nvmrc'])

/**
 * A row's file type, for its icon's colour (`FILE_TYPE`): a folder git ignores is
 * excluded (node_modules, build output), any other folder grey, a file by its
 * extension; lockfiles (`bun.lock`, `yarn.lock`) and anything unknown are text.
 */
export const fileType = (name: string, kind: string, excluded = false): FileType => {
  if (kind === 'dir') return excluded ? 'excluded' : 'folder'
  const lower = name.toLowerCase()
  if (CONFIG_NAMES.has(lower) || lower.startsWith('.env.')) return 'config'
  const ext = lower.includes('.') ? (lower.split('.').pop() ?? '') : ''
  return TYPE_BY_EXT.get(ext) ?? 'text'
}

/**
 * A git status letter's colour, in the kit's meanings: modified amber, new
 * green, deleted or conflicted red, renamed or copied blue.
 */
export const statusColor = (status: string | undefined): string | undefined => {
  if (!status) return undefined
  if (status === 'D' || status === 'U') return C.bad
  if (status === 'A' || status === '?') return C.ok
  if (status === 'M' || status === 'T') return C.warn
  if (status === 'R' || status === 'C') return C.blue
  return GRAY.mid
}

/**
 * The colour Claude's activity lights a row in. On a row: reads blue (live),
 * writes amber (changed, as git marks a modified file), commits green, failures
 * red. On the branch line purple is a merge, as everywhere in the kit.
 */
export const toneColor = (tone: string, branch = false): string => {
  if (tone === 'green') return C.ok
  if (tone === 'red') return C.bad
  if (tone === 'orange') return C.warn
  if (tone === 'purple') return branch ? C.purple : C.blue
  return C.blue
}

/** An activity's Octicon, by what git or gh did. */
export const activityIcon = (a: Activity) => {
  const kind = a.kind
  if (/\bcommit\b/.test(kind)) return 'git-commit'
  if (/\bpush\b/.test(kind)) return 'repo-push'
  if (/\b(pull|fetch|clone)\b/.test(kind)) return 'sync'
  if (/\b(merge|rebase|cherry-pick)\b/.test(kind)) return 'pr-merged'
  if (/^gh pr\b/.test(kind)) return 'pr-open'
  if (/^gh issue\b/.test(kind)) return 'issue-opened'
  if (/\b(reset|restore|revert|rm)\b/.test(kind)) return 'alert'
  return GLYPH.branch
}

const activityColor = (a: Activity) => (a.state === 'failed' ? C.bad : a.state === 'running' ? C.blue : C.ok)

export const renderDesktop = (els: DesktopElements, v: DesktopView, act: DesktopActions): RenderElement => {
  const { Box, Text, Button, Input } = els
  const { t } = v
  const k = kit(els, 'desktop', v.columns)
  const bright = new Set(t.flashOn ? t.flash : [])
  const dimmed = new Set(t.flashOn ? t.flashDim : [])
  const ignored = new Set(t.ignored)
  const untracked = new Set(t.untrackedDirs)

  /** An icon in a fixed column, so every name starts at one x. */
  const lead = (key: string, icon: RenderElement) => (
    <Box key={key} width={2} flexShrink={0} flexDirection="row" alignItems="center">
      {icon}
    </Box>
  )

  /**
   * An action drawn as its icon. The desktop draws a Button as its label text and
   * no children, so the icon (an SVG, named by `label` as its alt) sits in a box
   * and a Button with a blank label the icon's size lies over it: a press anywhere
   * on the icon is a press of the Button, its key the action's address. The label
   * is two Braille blanks (U+2800): they draw nothing, as spaces do, but no
   * renderer trims or collapses them.
   */
  const iconButton = (key: string, label: string, icon: string, color: string, onPress: () => void) => (
    <Box key={`ib-${key}`} position="relative" width={2} height={1} flexShrink={0} flexDirection="row" alignItems="center" justifyContent="center">
      {k.icon(icon, color, undefined, { alt: label })}
      <Box position="absolute" top={0} left={0}>
        <Button key={key} plain label={BLANK} onPress={onPress} />
      </Box>
    </Box>
  )

  /** A row: the left side gives way (truncates), the right side keeps its figures. */
  const line = (key: string, left: (RenderElement | null)[], right: (RenderElement | null)[], extra: Record<string, unknown> = {}) => (
    <Box key={key} flexDirection="row" justifyContent="space-between" alignItems="center" gap={SPACE.item} width="100%" {...extra}>
      <Box flexDirection="row" alignItems="center" flexShrink={1} minWidth={0} overflow="hidden">
        {left}
      </Box>
      <Box flexDirection="row" alignItems="center" gap={SPACE.pair} flexShrink={0}>
        {right}
      </Box>
    </Box>
  )

  /** A folder's file counts: new, modified, deleted, each its letter dim and its figure in its colour. */
  const counts = (key: string, c: [number, number, number] | undefined): RenderElement[] => {
    if (!c) return []
    const parts: [string, number, string][] = [
      ['?', c[0], C.ok],
      ['M', c[1], C.warn],
      ['D', c[2], C.bad],
    ]
    return parts
      .filter(([, n]) => n > 0)
      .map(([letter, n, color]) => (
        <Text key={`${key}-${letter}`}>
          <Text color={GRAY.dark}>{letter}</Text>
          <Text color={color}>{String(n)}</Text>
        </Text>
      ))
  }

  const lines = (key: string, loc: [number, number] | undefined): RenderElement[] => [
    ...(loc && loc[0] > 0 ? [<Text key={`${key}-add`} color={C.ok}>{`+${loc[0]}`}</Text>] : []),
    ...(loc && loc[1] > 0 ? [<Text key={`${key}-del`} color={C.bad}>{`−${loc[1]}`}</Text>] : []),
  ]

  // The header: the folder, then its actions.
  const name = t.top ? [t.top.split('/').pop() ?? t.top, t.prefix.replace(/\/$/, '')].filter(Boolean).join('/') : t.root.split('/').pop() || t.root
  const header = line(
    'head',
    [
      lead('icon', k.icon('folder-open', GRAY.mid)),
      <Text key="name" bold wrap="truncate">
        {name}
      </Text>,
    ],
    [
      iconButton('up', 'Up a folder', 'arrow-up', GRAY.mid, act.up),
      iconButton('cwd', 'Follow the working directory', 'home', v.follow ? GRAY.light : GRAY.dark, act.home),
      iconButton('refresh', 'Refresh', 'sync', GRAY.mid, act.refresh),
      iconButton('hidden', t.showHidden ? 'Hide hidden files' : 'Show hidden files', 'eye', t.showHidden ? GRAY.light : GRAY.dark, act.hidden),
      iconButton('size', t.showSize ? 'Show dates' : 'Show sizes', GLYPH.context, t.showSize ? GRAY.light : GRAY.dark, act.sizes),
      iconButton('collapse', 'Collapse all', 'fold', GRAY.mid, act.collapse),
      t.selected ? iconButton('unselect', 'Clear the selection', GLYPH.failed, GRAY.mid, act.unselect) : null,
    ],
    { marginBottom: SPACE.block },
  )

  // The branch: its name, ahead and behind, then the lines and files changed.
  const branch = () => {
    if (!t.top) {
      return line('branch', [lead('icon', k.icon(GLYPH.branch, GRAY.dark)), <Text key="none" color={GRAY.mid} wrap="truncate">no git repo · git status starts after git init</Text>], [], { marginBottom: SPACE.block })
    }
    if (!t.branch) return null
    const b = t.branch
    const flashing = bright.has(v.branchRow)
    const tone = flashing ? toneColor(t.flashTones[v.branchRow] ?? 'teal', true) : undefined
    const totals = t.diff[t.root] ?? [0, 0]
    const rootCounts = counts('root', t.counts[t.root])
    const changed = [...lines('root', totals), ...rootCounts]
    return line(
      'branch',
      [
        lead('icon', k.icon(GLYPH.branch, tone ?? GRAY.mid)),
        // Never squeezed out: the figures on the right leave it a few letters (fewer when
        // the name is shorter, so a short name doesn't leave a gap after it).
        <Box key="head" flexShrink={1} minWidth={Math.min(HEAD_MIN, [...b.head].length)}>
          <Text color={tone} wrap="truncate">
            {b.head}
          </Text>
        </Box>,
        b.ahead > 0 ? <Text key="ahead" color={GRAY.mid}>{` ↑${b.ahead}`}</Text> : null,
        b.behind > 0 ? <Text key="behind" color={GRAY.mid}>{` ↓${b.behind}`}</Text> : null,
        // The upstream as its host's icon (GitHub, GitLab, Forgejo, else a remote), its
        // name the icon's tooltip; none when the branch tracks nothing.
        // A local upstream (`main...main`, no remote) has no host to show.
        b.upstream && remoteName(b.upstream) ? (
          <Box key="upstream" flexShrink={0} marginLeft={SPACE.pair} flexDirection="row" alignItems="center">
            {k.icon(HOST_ICON[hostKind(b.host)], GRAY.dark, undefined, { tooltip: b.upstream })}
          </Box>
        ) : null,
      ],
      changed.length ? changed : [<Text key="clean" color={GRAY.mid}>clean</Text>],
      { marginBottom: SPACE.block },
    )
  }

  // The search field, the pane's first row, as wide as the pane. Its submit ("jump":
  // Enter opens the first match and clears the field) is drawn by the desktop as a
  // button beside it: every Input has one there, labelled "submit" if not named.
  const search = (
    <Box key="search" flexDirection="row" alignItems="center" gap={SPACE.pair} width="100%" marginBottom={SPACE.block}>
      {Input ? (
        // A column, so the field stretches across the box.
        <Box key="field" flexDirection="column" flexGrow={1} flexShrink={1} minWidth={0}>
          <Input key="q" placeholder="Search files" submitLabel="jump" autoFocus value={t.query} onInput={(q: string) => act.search(q)} onSubmit={(q: string) => act.jump(q)} />
        </Box>
      ) : null}
      {t.query ? iconButton('clear', 'Clear the search', GLYPH.failed, GRAY.mid, () => act.search('')) : null}
    </Box>
  )

  // One file or folder.
  const row = (r: Row) => {
    const n = r.node
    const own = t.git[n.id]
    const status = own ?? (underAny(dirname(n.id), untracked, t.root) ? '?' : undefined)
    const isIgnored = !status && underAny(n.id, ignored, t.root)
    const isBright = bright.has(n.id)
    const isDim = !isBright && dimmed.has(n.id)
    const tone = isBright || isDim ? toneColor(t.flashTones[n.id] ?? 'orange') : undefined
    const muted = isIgnored || n.hidden
    // The icon in its file type's colour (IntelliJ's), a folder git ignores in the excluded tone;
    // Claude's activity lights it in the activity's colour instead.
    const iconColor = tone ?? FILE_TYPE[fileType(n.name, n.kind, isIgnored)]
    const loc = t.diff[n.id]
    const meta = t.showSize
      ? n.kind === 'dir'
        ? n.id in t.dirSizes
          ? formatSize(t.dirSizes[n.id] ?? -1)
          : '…'
        : n.kind === 'file' || (n.kind === 'link' && n.size > 0)
          ? formatSize(n.size)
          : ''
      : loc || n.kind !== 'file' || !n.mtime
        ? ''
        : ago(v.now - n.mtime)
    const dirCounts = n.kind === 'dir' ? counts(n.id, t.counts[n.id]) : []
    const isCursor = n.id === t.cursor
    // A Button sizes to its label, so the name is cut to the room left here, with an ellipsis,
    // rather than clipped mid-letter: the pane less the indent, arrow, icon, figures and badge.
    const c = n.kind === 'dir' ? t.counts[n.id] : undefined
    const figures = [meta, loc?.[0] ? `+${loc[0]}` : '', loc?.[1] ? `−${loc[1]}` : '', ...(c ?? []).filter(x => x > 0).map(x => `?${x}`)].filter(Boolean)
    const room = Math.floor(v.columns - EDGE.left - EDGE.right - r.depth * SPACE.item - SPACE.item * 2 - 2 - figures.join(' ').length - SPACE.pair)
    const label = n.name.length > Math.max(4, room) ? `${n.name.slice(0, Math.max(3, room - 1))}…` : n.name
    return (
      <Box key={`row-${n.id}`} flexDirection="row" alignItems="center" width="100%" backgroundColor={isCursor ? TRACK : undefined}>
        {/* A rail in the activity's colour while Claude reads or writes it. */}
        <Box width={0.25} height={1} flexShrink={0} backgroundColor={isBright ? tone : undefined} />
        <Box width={EDGE.left - 0.25 + r.depth * SPACE.item} flexShrink={0} />
        <Box width={SPACE.item} flexShrink={0}>
          <Text color={GRAY.dark}>{n.kind === 'dir' ? (r.open ? '▾' : '▸') : ' '}</Text>
        </Box>
        {lead('icon', k.icon(fileIcon(n.name, n.kind, r.open), iconColor))}
        <Box flexGrow={1} flexShrink={1} minWidth={0} overflow="hidden">
          {/* The desktop draws a Button as its label, plain, never its children, so a name can't
              take its git colour or a weight here: it's dim when ignored or hidden, the git letter
              on the right says its state, the cursor's tint and the footer say what's selected. */}
          <Button key={n.id} plain label={label} {...(muted ? { dimColor: true } : {})} onPress={() => act.press(n.id)} />
        </Box>
        <Box flexDirection="row" alignItems="center" gap={SPACE.pair} flexShrink={0} marginLeft={SPACE.pair}>
          {meta ? <Text color={meta === '…' ? GRAY.dark : GRAY.mid}>{meta}</Text> : null}
          {lines(n.id, loc)}
          {dirCounts}
        </Box>
        <Box width={SPACE.item + EDGE.right} flexShrink={0} flexDirection="row" justifyContent="center">
          {dirCounts.length || !status ? null : <Text color={statusColor(status)}>{status}</Text>}
        </Box>
      </Box>
    )
  }

  const drawn = v.rows.slice(0, MAX_ROWS)
  const tree = (
    <Box key="tree" flexDirection="column" width="100%">
      {v.rows.length === 0 ? (
        <Box paddingLeft={EDGE.left}>
          <Text color={GRAY.mid}>{t.query ? 'no match' : 'empty'}</Text>
        </Box>
      ) : null}
      {drawn.map(row)}
      {v.rows.length > drawn.length ? (
        <Box paddingLeft={EDGE.left}>
          <Text color={GRAY.mid}>{`${v.rows.length - drawn.length} more; search to find them`}</Text>
        </Box>
      ) : null}
    </Box>
  )

  // The footer: what's selected (Claude sees it as context), and git's latest step.
  const chip = (a: Activity) => (
    <Box key="chip" flexDirection="row" alignItems="center" gap={SPACE.pair} flexShrink={0}>
      {k.icon(activityIcon(a), activityColor(a))}
      <Text color={a.state === 'running' ? C.blue : a.state === 'failed' ? C.bad : GRAY.light}>{a.state === 'running' ? `${a.label}…` : a.label}</Text>
      {a.state === 'done' && a.kind === 'git commit' && a.detail ? <Text color={GRAY.dark}>{a.detail.split(' ')[0] ?? ''}</Text> : null}
    </Box>
  )
  const selected = t.selected
  const footer =
    selected || v.latest
      ? line(
          'foot',
          selected
            ? [
                lead('icon', k.icon('file', GRAY.dark)),
                <Box key="path" flexShrink={1} minWidth={0}>
                  <Text color={GRAY.mid} wrap="truncate-start">
                    {v.shown(selected)}
                  </Text>
                </Box>,
                <Box key="open" flexShrink={0} marginLeft={SPACE.pair}>
                  <Button key="open" plain dimColor label="open" onPress={() => act.open(selected)} />
                </Box>,
              ]
            : [],
          [v.latest ? chip(v.latest) : null],
          { marginTop: SPACE.block },
        )
      : null

  return (
    <Box flexDirection="column" minHeight={Math.max(1, v.bodyRows)} paddingTop={SPACE.block}>
      <Box flexDirection="column" paddingLeft={EDGE.left} paddingRight={EDGE.right}>
        {search}
        {header}
        {branch()}
      </Box>
      {tree}
      <Box flexGrow={1} />
      {footer ? (
        <Box flexDirection="column" paddingLeft={EDGE.left} paddingRight={EDGE.right}>
          {footer}
        </Box>
      ) : null}
    </Box>
  )
}

files.hooks/git.ts:
import { drivesOn, isAbsolute, posix } from './tree'

export type GitAction = {
  kind: string
  verb: string
  running: string
  done: string
  tone: string
  icon: { nerd: string; plain: string }
  init?: boolean
}

const ICON = {
  commit: { nerd: '\u{f417}', plain: '●' },
  push: { nerd: '\u{f0552}', plain: '↑' },
  pull: { nerd: '\u{f0553}', plain: '↓' },
  branch: { nerd: '\u{f418}', plain: '⑂' },
  merge: { nerd: '\u{f419}', plain: '⑃' },
  pr: { nerd: '\u{f407}', plain: '⇄' },
  github: { nerd: '\u{f408}', plain: '◎' },
  stash: { nerd: '\u{f01bc}', plain: '≡' },
  undo: { nerd: '\u{f054c}', plain: '↶' },
  tag: { nerd: '\u{f412}', plain: '⌖' },
  git: { nerd: '\u{e702}', plain: '±' },
}

/**
 * The activity tones a lit row or git step takes. Changed in this fork: the names
 * only, no hex ramps; each draws in the kit's colour for its meaning (`toneColor`
 * in desktop.tsx), a theme key on the terminal through the kit's `termInk`.
 */
export const TONES = ['orange', 'green', 'teal', 'blue', 'purple', 'cyan', 'red'] as const

const GIT_VERBS: Record<string, Omit<GitAction, 'kind'>> = {
  commit: { verb: 'commit', running: 'committing', done: 'committed', tone: 'green', icon: ICON.commit },
  push: { verb: 'push', running: 'pushing', done: 'pushed', tone: 'teal', icon: ICON.push },
  pull: { verb: 'pull', running: 'pulling', done: 'pulled', tone: 'blue', icon: ICON.pull },
  fetch: { verb: 'fetch', running: 'fetching', done: 'fetched', tone: 'blue', icon: ICON.pull },
  checkout: { verb: 'checkout', running: 'checking out', done: 'checked out', tone: 'blue', icon: ICON.branch },
  switch: { verb: 'switch', running: 'switching', done: 'switched', tone: 'blue', icon: ICON.branch },
  branch: { verb: 'branch', running: 'branching', done: 'branched', tone: 'blue', icon: ICON.branch },
  merge: { verb: 'merge', running: 'merging', done: 'merged', tone: 'purple', icon: ICON.merge },
  rebase: { verb: 'rebase', running: 'rebasing', done: 'rebased', tone: 'purple', icon: ICON.merge },
  'cherry-pick': { verb: 'cherry-pick', running: 'cherry-picking', done: 'cherry-picked', tone: 'purple', icon: ICON.merge },
  stash: { verb: 'stash', running: 'stashing', done: 'stashed', tone: 'orange', icon: ICON.stash },
  reset: { verb: 'reset', running: 'resetting', done: 'reset', tone: 'red', icon: ICON.undo },
  restore: { verb: 'restore', running: 'restoring', done: 'restored', tone: 'red', icon: ICON.undo },
  revert: { verb: 'revert', running: 'reverting', done: 'reverted', tone: 'red', icon: ICON.undo },
  add: { verb: 'add', running: 'staging', done: 'staged', tone: 'green', icon: ICON.git },
  rm: { verb: 'rm', running: 'removing', done: 'removed', tone: 'red', icon: ICON.git },
  mv: { verb: 'mv', running: 'moving', done: 'moved', tone: 'orange', icon: ICON.git },
  tag: { verb: 'tag', running: 'tagging', done: 'tagged', tone: 'purple', icon: ICON.tag },
  init: { verb: 'init', running: 'initialising', done: 'initialised', tone: 'green', icon: ICON.git, init: true },
  clone: { verb: 'clone', running: 'cloning', done: 'cloned', tone: 'blue', icon: ICON.pull, init: true },
}

const GH_VERBS: Record<string, Omit<GitAction, 'kind'>> = {
  'pr create': { verb: 'pr create', running: 'opening PR', done: 'opened PR', tone: 'purple', icon: ICON.pr },
  'pr merge': { verb: 'pr merge', running: 'merging PR', done: 'merged PR', tone: 'purple', icon: ICON.merge },
  'pr checkout': { verb: 'pr checkout', running: 'checking out PR', done: 'checked out PR', tone: 'blue', icon: ICON.pr },
  'pr comment': { verb: 'pr comment', running: 'commenting on PR', done: 'commented on PR', tone: 'purple', icon: ICON.pr },
  'pr review': { verb: 'pr review', running: 'reviewing PR', done: 'reviewed PR', tone: 'purple', icon: ICON.pr },
  'repo clone': { verb: 'repo clone', running: 'cloning', done: 'cloned', tone: 'blue', icon: ICON.github, init: true },
  'release create': { verb: 'release create', running: 'releasing', done: 'released', tone: 'purple', icon: ICON.tag },
  'issue create': { verb: 'issue create', running: 'opening issue', done: 'opened issue', tone: 'purple', icon: ICON.github },
}

const READ_ONLY_GIT = new Set(['status', 'log', 'diff', 'show', 'blame', 'rev-parse', 'ls-files', 'grep', 'describe', 'config', 'remote', 'reflog', 'shortlog', 'help', 'version', 'check-ignore'])

function segments(command: string, seps: string[] = []): string[][] {
  const out: string[][] = []
  let cur: string[] = []
  let tok = ''
  let quote = ''
  let has = false
  const endTok = () => {
    if (has) cur.push(tok)
    tok = ''
    has = false
  }
  const endSeg = () => {
    endTok()
    if (cur.length) out.push(cur)
    cur = []
  }
  for (let i = 0; i < command.length; i++) {
    const ch = command[i] ?? ''
    if (quote) {
      if (ch === quote) quote = ''
      else if (ch === '\\' && quote === '"' && i + 1 < command.length) tok += command[++i]
      else tok += ch
    } else if (ch === '"' || ch === "'") {
      quote = ch
      has = true
    } else if (ch === '\\' && i + 1 < command.length) {
      tok += command[++i]
      has = true
    } else if (ch === '#' && !has) {
      while (i + 1 < command.length && command[i + 1] !== '\n') i++
    } else if (ch === ' ' || ch === '\t') endTok()
    else if (ch === '\n' || ch === ';') {
      seps.push(';')
      endSeg()
    } else if (ch === '&' && (command[i - 1] === '>' || command[i + 1] === '>')) {
      tok += ch
      has = true
    } else if (ch === '&' || ch === '|') {
      const twice = command[i + 1] === ch
      if (twice) i++
      seps.push(twice ? ch + ch : ch)
      endSeg()
    } else {
      tok += ch
      has = true
    }
  }
  endSeg()
  if (!quote) return out
  seps.push(';')
  return command
    .split(/&&|\|\||;|\||\n/)
    .map(s => s.trim().split(/\s+/).filter(Boolean))
    .filter(s => s.length > 0)
}

function stripGlobals(tokens: string[]): string[] {
  const out = [...tokens]
  if (out[0] === 'env') out.shift()
  while (out.length && /^[A-Z_][A-Z0-9_]*=/.test(out[0] ?? '')) out.shift()
  return out
}

function gitVerb(tokens: string[]): number {
  let i = 1
  while (i < tokens.length && (tokens[i] ?? '').startsWith('-')) {
    if (tokens[i] === '-C' || tokens[i] === '-c') i++
    i++
  }
  return i
}

function gitReadOnly(verb: string, rest: string[]): boolean {
  if (!verb || READ_ONLY_GIT.has(verb)) return true
  if (verb === 'stash') return ['list', 'show'].includes(rest[0] ?? '')
  if (verb === 'branch') return rest.every(t => t.startsWith('-'))
  if (verb === 'tag') return rest.length === 0 || rest.some(t => /^(-l|--list|-n\d*|--contains|--points-at|--merged|--no-merged|-v|--verify)$/.test(t))
  return false
}

export function chainOf(command: string): { size: number; and: boolean } {
  const seps: string[] = []
  const size = segments(command, seps).length
  return { size, and: seps.every(s => s === '&&') }
}

export function gitActions(command: string): GitAction[] {
  const out: GitAction[] = []
  for (const raw of segments(command)) {
    const tokens = stripGlobals(raw)
    const head = tokens[0]?.split('/').pop()
    if (head === 'git') {
      const i = gitVerb(tokens)
      const verb = tokens[i] ?? ''
      const rest = tokens.slice(i + 1)
      if (gitReadOnly(verb, rest)) continue
      const spec = verb === 'checkout' && rest.includes('--') ? GIT_VERBS.restore : GIT_VERBS[verb]
      if (spec) out.push({ kind: `git ${verb}`, ...spec })
    } else if (head === 'gh') {
      const pair = `${tokens[1] ?? ''} ${tokens[2] ?? ''}`
      const spec = GH_VERBS[pair]
      if (spec) out.push({ kind: `gh ${pair}`, ...spec })
    }
  }
  return out
}

export const BRANCH_ICON = ICON.branch

const READERS = new Set(['rg', 'grep', 'egrep', 'fgrep', 'find', 'fd', 'fdfind', 'cat', 'head', 'tail', 'bat', 'less', 'more', 'ls', 'eza', 'tree', 'wc', 'sed', 'awk', 'jq'])
const PATTERN_FIRST = new Set(['rg', 'grep', 'egrep', 'fgrep', 'sed', 'awk', 'jq'])
const OUTPUT_PATHS = new Set(['rg', 'grep', 'egrep', 'fgrep', 'find', 'fd', 'fdfind'])

function tidy(path: string): string {
  const s = path.replace(/\/+$/, '')
  return s === '' ? '/' : /^[A-Za-z]:$/.test(s) && isAbsolute(`${s}/`) ? `${s}/` : s
}

export function resolve(cwd: string, p: string, home = ''): string {
  let path = posix(p)
  if (home && (path === '~' || path.startsWith('~/'))) path = home + path.slice(1)
  const drive = isAbsolute(path) && !path.startsWith('/') ? path.slice(0, 2) : ''
  const parts = isAbsolute(path) ? [drive] : posix(cwd).replace(/\/+$/, '').split('/')
  for (const seg of path.slice(drive.length).split('/')) {
    if (!seg || seg === '.') continue
    if (seg === '..') {
      if (parts.length > 1) parts.pop()
    } else parts.push(seg)
  }
  return tidy(parts.join('/'))
}

const WRITE_FLAGS = /^-(delete|exec|execdir|ok|okdir|fprint\w*|fls|x|X|-exec|-exec-batch)$/

export function readOnly(command: string): boolean {
  const bare = ` ${command}`.replace(/\d*>&\d/g, ' ').replace(/(\d*|&)>>?\s*\/dev\/null/g, ' ')
  if (/[^>]>[^>&]|>>/.test(bare)) return false
  return segments(command).every(raw => {
    const tokens = stripGlobals(raw)
    const head = tokens[0]?.split('/').pop() ?? ''
    if (head === 'cd' || head === 'echo' || head === 'printf' || head === 'true' || head === 'pwd') return true
    if (head === 'git') {
      const i = gitVerb(tokens)
      return gitReadOnly(tokens[i] ?? '', tokens.slice(i + 1))
    }
    if (head === 'sed') return !tokens.some(t => /^-i/.test(t))
    if (head === 'find' || head === 'fd' || head === 'fdfind') return !tokens.some(t => WRITE_FLAGS.test(t))
    return READERS.has(head)
  })
}

export function readTargets(command: string, sessionCwd: string, stdout: string, home = ''): string[] {
  let cwd = sessionCwd
  const out = new Set<string>()
  let listsPaths = false
  for (const raw of segments(command)) {
    const tokens = stripGlobals(raw).map(t => posix(t.replace(/^["']|["']$/g, '')))
    const head = tokens[0]?.split('/').pop() ?? ''
    if (head === 'cd' && tokens[1]) {
      cwd = resolve(cwd, tokens[1], home)
      continue
    }
    if (!READERS.has(head)) continue
    if (head === 'sed' && tokens.some(t => /^-i/.test(t))) continue
    if (OUTPUT_PATHS.has(head)) listsPaths = true
    const args = tokens.slice(1)
    let skipPattern = PATTERN_FIRST.has(head) && !args.some(t => t === '-e' || t === '-f' || t === '--files')
    for (let i = 0; i < args.length; i++) {
      const a = args[i] ?? ''
      if (a.startsWith('-')) {
        if (/^-(e|f|g|t|T|m|A|B|C|-glob|-type|-max-count|name|iname|maxdepth|mindepth)$/.test(a)) i++
        continue
      }
      if (skipPattern) {
        skipPattern = false
        continue
      }
      if (/[*?<>|]/.test(a)) continue
      out.add(resolve(cwd, a, home))
    }
  }
  if (listsPaths) {
    for (const line of stdout.split('\n').slice(0, 400)) {
      const path = posix(line).match(drivesOn() ? /^((?:[A-Za-z]:)?[^:\0]+?)(?::\d+[:-]|$|:)/ : /^([^:\0]+?)(?::\d+[:-]|$|:)/)?.[1]?.trim()
      if (path && !path.includes(' ')) out.add(resolve(cwd, path, home))
    }
  }
  return [...out].slice(0, 60)
}

files.hooks/rows.tsx:
// Changed in this fork (awesome-claude) for the kit's terminal look: colours are the
// kit's terminal inks (theme keys or dim), and the shimmer is a bold band sweeping
// through a row drawn in its activity's colour, not a hex gradient. The cursor row is
// the kit's selected list row: a `▌` gutter mark in `suggestion` (dim while the pane
// doesn't have the keyboard), never a background, which no fixed hex reads on every theme.
// The scrollbar is only its thumb, dim.
import type { ClientModule } from 'claude-code'

/**
 * One run of a row: `c` a colour (an engine theme key, never a hex: the kit's
 * `termInk` gives it), `dc` the terminal's dim, `sh` a shimmer tone (a key of
 * `tones`), `dim` the faint flash.
 */
export type Seg = { t: string; c?: string; dc?: boolean; b?: boolean; s?: boolean; i?: boolean; sh?: string; dim?: boolean; one?: boolean; spin?: boolean; tab?: string }
export type RowSpec = { id: string; left: Seg[]; right: Seg[] }
export type RowsProps = {
  rows: RowSpec[]
  /** The cursor row's id: its one-cell gutter holds `mark`. */
  active: string
  /** The kit's selected-row mark (`MARK.selected`) and its colour (a theme key). */
  mark: string
  markColor?: string
  /** Whether the pane has the keyboard: the mark is dim while it hasn't. */
  focused: boolean
  /** Each shimmer tone's colour on the terminal (a theme key, from the kit's `termInk`). */
  tones: Record<string, string>
  spinner?: string[]
  pointer?: boolean
  /** The scrollbar: its thumb a dim `┃`, no track (a full-height rule beside the names read as a border). */
  bar?: { pos: number; size: number }
  preview?: { text: string; path: string; startLine: number; markdown: boolean }
}
type Local = { phase: number; drag: boolean; ref: { stop?: () => void; unpoint?: () => void } }

const TICK_MS = 90
const FRAMES = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']

/** Whether letter `i` of `len` sits in the band the shimmer sweeps across a name. */
function inBand(i: number, phase: number, len: number): boolean {
  const band = ((phase * 1.6) % (len + 8)) - 4
  return Math.abs(i - band) < 1.8
}

const Rows: ClientModule<RowsProps, Local> = (props, surface) => {
  const { Box, Text } = surface.elements
  let state = surface.state
  if (state === undefined) {
    state = { phase: 0, drag: false, ref: {} }
    surface.setState(state)
  }
  const lit = props.rows.some(r => r.left.some(s => s.sh || s.spin) || r.right.some(s => s.sh || s.spin))
  if (lit && !state.ref.stop) {
    state.ref.stop = surface.every(TICK_MS, () => {
      const cur = surface.state
      if (cur) surface.setState({ ...cur, phase: cur.phase + 1 })
    })
  } else if (!lit && state.ref.stop) {
    state.ref.stop()
    state.ref.stop = undefined
  }
  if (props.pointer === false) {
    state.ref.unpoint?.()
    state.ref.unpoint = undefined
  } else state.ref.unpoint = surface.onPointer(e => {
    const cur = surface.state ?? state
    const span = Math.max(1, props.rows.length - 1)
    const onBar = Boolean(props.bar) && e.x >= surface.columns - 1
    if (props.bar && (cur.drag || (onBar && e.type === 'down' && (e.button ?? 'left') === 'left'))) {
      if (e.type === 'up' || e.type === 'leave') {
        surface.setState({ ...cur, drag: false })
        return
      }
      if (e.type === 'down' || e.type === 'move') {
        if (!cur.drag) surface.setState({ ...cur, drag: true })
        surface.post({ scrollTo: Math.max(0, Math.min(1, e.y / span)) })
        return
      }
    }
    if (e.type === 'leave' || e.y < 0 || e.y >= props.rows.length) return
    const row = props.rows[e.y]
    if (e.type === 'down' && e.button === 'right' && row?.id) {
      surface.post({ copy: row.id, shift: Boolean(e.shift) })
      return
    }
    if (e.type !== 'down' || (e.button ?? 'left') !== 'left' || !row) return
    // After the one-cell gutter.
    let x = 1
    for (const seg of row.left) {
      const w = [...seg.t].length
      if (seg.tab && e.x >= x && e.x < x + w) {
        surface.post({ tab: seg.tab })
        return
      }
      x += w
    }
    if (row.id) surface.post({ press: row.id, ctrl: Boolean(e.ctrl), shift: Boolean(e.shift) })
  })
  surface.onKey(e => surface.post({ key: e.key, ctrl: Boolean(e.ctrl), shift: Boolean(e.shift) }))
  // The preview draws in this same element, so the focus a click gave the tree stays put.
  if (props.preview) {
    const { Markdown, Code } = surface.elements
    const p = props.preview
    return p.markdown ? <Markdown text={p.text} /> : <Code source={p.text} path={p.path} startLine={p.startLine} wrap="truncate-end" />
  }
  const frames = props.spinner?.length ? props.spinner : FRAMES
  const draw = (s: Seg) => {
    if (s.spin) {
      return (
        <Text color={s.c} bold={s.b}>
          {s.t + (frames[state.phase % frames.length] ?? '')}
        </Text>
      )
    }
    const tone = s.sh ? props.tones[s.sh] : undefined
    if (!tone) {
      return (
        <Text color={s.c} dimColor={s.dc} bold={s.b} strikethrough={s.s} italic={s.i}>
          {s.t}
        </Text>
      )
    }
    // The faint flash (files Claude touched a moment ago) stays dim and still.
    if (s.one || s.dim) {
      return (
        <Text color={tone} dimColor={s.dim} bold={s.b}>
          {s.t}
        </Text>
      )
    }
    const chars = [...s.t]
    return (
      <Text color={tone}>
        {chars.map((ch, i) => (
          <Text bold={s.b || inBand(i, state.phase, chars.length)}>{ch}</Text>
        ))}
      </Text>
    )
  }
  return (
    <Box flexDirection="column">
      {props.rows.map((r, i) => (
        <Box flexDirection="row" height={1} overflow="hidden">
          <Box width={1} flexShrink={0}>
            {r.id && r.id === props.active ? (
              <Text color={props.markColor} dimColor={!props.focused || undefined}>
                {props.mark}
              </Text>
            ) : (
              <Text> </Text>
            )}
          </Box>
          <Box flexShrink={1} overflow="hidden">
            {r.left.map(draw)}
          </Box>
          <Box flexGrow={1} />
          {r.right.map(draw)}
          {props.bar && <Text dimColor>{i >= props.bar.pos && i < props.bar.pos + props.bar.size ? ' ┃' : '  '}</Text>}
        </Box>
      ))}
    </Box>
  )
}

export default Rows

files.hooks/tree.ts:
import type { Branch, FileNode, FileTree } from '../types'
import { stronger } from './icons'

export type Entry = { name: string; kind: 'file' | 'dir' | 'other'; mtimeMs: number; size: number; isLink: boolean }
export type Row = { node: FileNode; depth: number; open: boolean }

const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' })

export function emptyTree(root: string): FileTree {
  return {
    root,
    nodes: [],
    expanded: [],
    cursor: '',
    selected: '',
    query: '',
    showHidden: true,
    showSize: false,
    dirSizes: {},
    git: {},
    diff: {},
    ignored: [],
    untrackedDirs: [],
    top: '',
    prefix: '',
    branch: null,
    counts: {},
    flash: [],
    flashDim: [],
    flashOn: false,
    flashTones: {},
    scroll: null,
    preview: '',
    previewTop: 0,
  }
}

export function join(dir: string, name: string): string {
  return dir.endsWith('/') ? dir + name : `${dir}/${name}`
}

let drives = false

export function dirname(path: string): string {
  if (drives && /^[A-Za-z]:\/[^/]*$/.test(path)) return path.slice(0, 3)
  const i = path.lastIndexOf('/')
  return i <= 0 ? '/' : path.slice(0, i)
}

export function useDrives(on: boolean): void {
  drives = on
}

export function drivesOn(): boolean {
  return drives
}

export function posix(path: string): string {
  if (!drives) return path
  return path.replace(/\\/g, '/').replace(/^\/([A-Za-z])(\/|$)/, (_, d: string) => `${d.toUpperCase()}:/`)
}

export function dropBelow(nodes: FileNode[], dirs: string[]): FileNode[] {
  if (dirs.length === 0) return nodes
  const under = (id: string) => dirs.some(d => id !== d && inside(d, id))
  const gone = new Set(dirs)
  return nodes.filter(n => !under(n.id)).map(n => (gone.has(n.id) && n.loaded ? { ...n, loaded: false } : n))
}

export function isAbsolute(path: string): boolean {
  return path.startsWith('/') || (drives && /^[A-Za-z]:\//.test(path))
}

export function inside(root: string, path: string): boolean {
  return path === root || path.startsWith(root.endsWith('/') ? root : `${root}/`)
}

export function toNodes(dir: string, list: Entry[]): FileNode[] {
  return list
    .map(e => ({
      id: join(dir, e.name),
      parent: dir,
      name: e.name,
      kind: e.isLink ? ('link' as const) : e.kind === 'dir' ? ('dir' as const) : ('file' as const),
      hidden: e.name.startsWith('.'),
      mtime: e.mtimeMs,
      size: e.size,
      loaded: false,
    }))
    .sort((a, b) => (a.kind === 'dir' ? 0 : 1) - (b.kind === 'dir' ? 0 : 1) || collator.compare(a.name, b.name))
}

export function replaceChildren(nodes: FileNode[], listed: Map<string, FileNode[]>): FileNode[] {
  if (listed.size === 0) return nodes
  const keep = new Map<string, FileNode>()
  for (const n of nodes) if (listed.has(n.parent)) keep.set(n.id, n)
  const freshIds = new Set<string>()
  for (const kids of listed.values()) for (const k of kids) freshIds.add(k.id)
  const gone = new Set([...keep.keys()].filter(id => !freshIds.has(id)))
  const under = (id: string) => {
    if (gone.size === 0) return false
    for (let dir = dirname(id), prev = id; dir !== prev; prev = dir, dir = dirname(dir)) if (gone.has(dir)) return true
    return false
  }
  const fresh: FileNode[] = []
  for (const kids of listed.values()) {
    for (const k of kids) {
      if (under(k.id)) continue
      const old = keep.get(k.id)
      fresh.push(old && old.kind === 'dir' && k.kind === 'dir' ? { ...k, loaded: old.loaded } : k)
    }
  }
  const out = nodes.filter(n => !listed.has(n.parent) && !under(n.id))
  return [...out.map(n => (listed.has(n.id) ? { ...n, loaded: true } : n)), ...fresh]
}

export type GitStatus = {
  git: Record<string, string>
  ignored: string[]
  untrackedDirs: string[]
  branch: Branch | null
  files: Record<string, Change>
}

export type Change = 'new' | 'mod' | 'del'

export function parseBranch(record: string): Branch {
  const body = record.replace(/^## /, '')
  if (body.startsWith('HEAD (no branch)')) return { head: 'detached', upstream: '', host: '', ahead: 0, behind: 0 }
  const head = body.match(/^(?:No commits yet on |Initial commit on )?(.+?)(?:\.\.\.|\s|$)/)?.[1] ?? body
  const upstream = body.match(/\.\.\.(\S+)/)?.[1] ?? ''
  const ahead = Number(body.match(/ahead (\d+)/)?.[1] ?? 0)
  const behind = Number(body.match(/behind (\d+)/)?.[1] ?? 0)
  return { head, upstream, host: '', ahead, behind }
}

/** The remote an upstream lives on: `origin` of `origin/feat/x`. */
export function remoteName(upstream: string): string {
  const slash = upstream.indexOf('/')
  return slash > 0 ? upstream.slice(0, slash) : ''
}

/**
 * A remote URL's host, lowercased: `https://github.com/o/r.git`,
 * `ssh://git@host:22/o/r`, scp-like `git@gitlab.com:o/r.git`. Empty for a local
 * path or anything else without one.
 */
export function remoteHost(url: string): string {
  const u = url.trim()
  const full = u.match(/^[a-z][a-z0-9+.-]*:\/\/(?:[^@/]*@)?(\[[^\]]+\]|[^/:?#]+)/i)
  if (full) return (full[1] ?? '').toLowerCase()
  const scp = u.match(/^(?:[^@/]+@)?([^/:]+):(?!\/)/)
  return scp ? (scp[1] ?? '').toLowerCase() : ''
}

/** Where an upstream lives, by its remote's host. */
export type HostKind = 'github' | 'gitlab' | 'forgejo' | 'other'

/** GitHub by its host, GitLab and Forgejo by theirs or a host that names them (a self-hosted `gitlab.corp`). */
export function hostKind(host: string): HostKind {
  const h = host.toLowerCase()
  if (h === 'github.com' || h.endsWith('.github.com')) return 'github'
  if (h.includes('gitlab')) return 'gitlab'
  if (h.includes('codeberg') || h.includes('forgejo')) return 'forgejo'
  return 'other'
}

/** Each host's icon (kit/icons.ts): GitHub's mark, GitLab's, Forgejo's, else a generic remote. */
export const HOST_ICON: Record<HostKind, string> = { github: 'mark-github', gitlab: 'gitlab', forgejo: 'forgejo', other: 'cloud' }

/** Each host's mark on the terminal, which has no glyph for them: two letters, or ⇅ for any other remote. */
export const HOST_MARK: Record<HostKind, string> = { github: 'gh', gitlab: 'gl', forgejo: 'fj', other: '⇅' }

export function mapper(root: string, prefix: string): (rel: string) => string | null {
  return rel => (rel.startsWith(prefix) ? join(root, rel.slice(prefix.length).replace(/\/$/, '')).replace(/\/$/, '') : null)
}

export function parseGit(stdout: string, root: string, prefix: string): GitStatus {
  const map = mapper(root, prefix)
  const git: Record<string, string> = {}
  const ignored: string[] = []
  const untrackedDirs: string[] = []
  const files: Record<string, Change> = {}
  let branch: Branch | null = null
  const parts = stdout.split('\0')
  for (let i = 0; i < parts.length; i++) {
    const rec = parts[i] ?? ''
    if (rec.startsWith('## ')) {
      branch = parseBranch(rec)
      continue
    }
    if (rec.length < 4) continue
    const xy = rec.slice(0, 2)
    const raw = rec.slice(3)
    if (xy[0] === 'R' || xy[0] === 'C') i++
    const path = map(raw)
    if (!path) continue
    if (xy === '!!') {
      ignored.push(path)
      continue
    }
    if (xy === '??' && raw.endsWith('/')) untrackedDirs.push(path)
    else files[path] = xy === '??' || (xy.includes('A') && !xy.includes('D')) ? 'new' : xy.includes('D') && !/U/.test(xy) ? 'del' : 'mod'
    const letter =
      xy === '??'
        ? '?'
        : /U/.test(xy) || xy === 'AA' || xy === 'DD'
          ? 'U'
          : (['D', 'M', 'R', 'C', 'A', 'T'].find(c => xy.includes(c)) ?? '')
    if (!letter) continue
    git[path] = stronger(git[path], letter)
    let dir = dirname(path)
    while (dir.length >= root.length && dir !== '/') {
      git[dir] = stronger(git[dir], letter)
      if (dir === root) break
      dir = dirname(dir)
    }
  }
  return { git, ignored, untrackedDirs, branch, files }
}

export function parseNumstat(stdout: string, root: string, prefix: string, into: Record<string, [number, number]>): void {
  const map = mapper(root, prefix)
  const parts = stdout.split('\0')
  for (let i = 0; i < parts.length; i++) {
    const rec = parts[i] ?? ''
    if (!rec) continue
    const m = rec.match(/^(-|\d+)\t(-|\d+)\t(.*)$/s)
    if (!m) continue
    let path = m[3] ?? ''
    if (path === '') {
      i += 2
      path = parts[i] ?? ''
    }
    if (!path) continue
    const add = m[1] === '-' ? 0 : Number(m[1])
    const del = m[2] === '-' ? 0 : Number(m[2])
    const abs = map(path)
    if (!abs) continue
    const prev = into[abs] ?? [0, 0]
    into[abs] = [prev[0] + add, prev[1] + del]
  }
}

export function rollUp(diff: Record<string, [number, number]>, root: string): Record<string, [number, number]> {
  const out: Record<string, [number, number]> = { ...diff }
  for (const [path, [add, del]] of Object.entries(diff)) {
    let dir = dirname(path)
    while (dir.length >= root.length && dir !== '/') {
      const prev = out[dir] ?? [0, 0]
      out[dir] = [prev[0] + add, prev[1] + del]
      if (dir === root) break
      dir = dirname(dir)
    }
  }
  return out
}

export function rollCounts(files: Record<string, Change>, root: string): Record<string, [number, number, number]> {
  const out: Record<string, [number, number, number]> = {}
  const slot = { new: 0, mod: 1, del: 2 } as const
  for (const [path, change] of Object.entries(files)) {
    let dir = dirname(path)
    while (dir.length >= root.length && dir !== '/') {
      const cur = out[dir] ?? [0, 0, 0]
      cur[slot[change]] += 1
      out[dir] = cur
      if (dir === root) break
      dir = dirname(dir)
    }
  }
  return out
}

export function underAny(id: string, set: Set<string>, root: string): boolean {
  if (set.size === 0) return false
  let cur = id
  while (cur.length >= root.length) {
    if (set.has(cur)) return true
    const up = dirname(cur)
    if (up === cur) break
    cur = up
  }
  return false
}

export function ancestorsOf(id: string, root: string): string[] {
  const out: string[] = []
  if (!root) return out
  for (let dir = dirname(id), prev = id; dir !== prev && dir !== root && inside(root, dir); prev = dir, dir = dirname(dir)) out.push(dir)
  return out
}

export function relative(root: string, path: string): string {
  return path === root ? '' : path.slice(root.endsWith('/') ? root.length : root.length + 1)
}

export function visibleRows(t: FileTree): Row[] {
  const kids = new Map<string, FileNode[]>()
  for (const n of t.nodes) {
    if (!t.showHidden && n.hidden) continue
    const list = kids.get(n.parent)
    if (list) list.push(n)
    else kids.set(n.parent, [n])
  }
  const q = t.query.trim().toLowerCase()
  let keep: Set<string> | null = null
  if (q) {
    keep = new Set()
    for (const n of t.nodes) {
      if (!relative(t.root, n.id).toLowerCase().includes(q)) continue
      keep.add(n.id)
      for (const a of ancestorsOf(n.id, t.root)) keep.add(a)
    }
  }
  const open = new Set(t.expanded)
  const rows: Row[] = []
  const walk = (dir: string, depth: number) => {
    for (const n of kids.get(dir) ?? []) {
      if (keep && !keep.has(n.id)) continue
      const isOpen = n.kind === 'dir' && (keep ? kids.has(n.id) : open.has(n.id))
      rows.push({ node: n, depth, open: isOpen })
      if (isOpen) walk(n.id, depth + 1)
    }
  }
  walk(t.root, 0)
  return rows
}

export function stamp(ms: number): string {
  if (!ms) return ''
  const d = new Date(ms)
  const p = (v: number) => String(v).padStart(2, '0')
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`
}

export function formatSize(bytes: number): string {
  if (bytes < 0) return '?'
  if (bytes < 1024) return `${bytes} B`
  const units = ['K', 'M', 'G', 'T']
  let v = bytes / 1024
  let i = 0
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024
    i++
  }
  return `${v < 100 ? v.toFixed(1) : Math.round(v)} ${units[i]}`
}

files.kit/skin.ts:
/**
 * A skin: the colours the kit draws with on the app surfaces (desktop, VS Code, mobile), one per
 * meaning (see kit/tokens.ts). Each zen theme pack gives one (kit/skins.ts, made from the pack's
 * palette by zen's `src/harness/claude-code/skins.ts`); a mod wears one with `wear()`.
 *
 * The terminal never draws these values: it draws each meaning in the terminal theme key that
 * means the same thing (THEME_KEY, TERM_TINT in kit/tokens.ts), whatever the skin, so a mod
 * follows the person's terminal theme.
 *
 * Every value is #rrggbb, and every value is its meaning's own: no two meanings share a value,
 * as the terminal finds a meaning by its value. Greys may share one another's.
 */
export type Skin = {
  /** The pack's name, as zen's toolbar shows it. */
  readonly label: string
  /** Finished well: checks passed, an agent done. */
  readonly ok: string
  /** Getting close to a limit: 75% and up, the compaction mark. */
  readonly warn: string
  /** Failed, conflicted, 90% and up. */
  readonly bad: string
  /** Live or in progress: running, pending, the activity series. */
  readonly blue: string
  /** Merged. */
  readonly purple: string
  /** A tint for parts within one chart, never a status. */
  readonly cyan: string
  /** Quantity ink: what a bar or gauge is drawn in when it only says how much. */
  readonly slate: string
  /** A tint for parts within one chart, never a status. */
  readonly orchid: string
  /** Shades within one chart: the live colour and the quantity ink, each base first, then darker, lighter, darkest. */
  readonly ramp: { readonly blue: readonly [string, string, string, string]; readonly slate: readonly [string, string, string, string] }
  /** Text, icons and marks that should recede. */
  readonly muted: string
  /** Text below the main text, each a step quieter. */
  readonly gray: { readonly light: string; readonly mid: string; readonly dark: string }
}

files.kit/perf.ts:
/**
 * What a mod costs: how often each named thing ran, how long it took, and how
 * much of the last minute it spent. Each compiled mod gets its own copy of the
 * kit, so these are that mod's numbers. Recording never redraws: the footer
 * shows them as of the pane's latest draw, so measuring adds no load.
 *
 *   const done = perf.start('render'); …; done()
 *   await perf.time('git', () => run(...))
 *   perf.count('state write')
 */

const now = (): number => (globalThis as { performance?: { now(): number } }).performance?.now() ?? Date.now()

const WINDOW = 60_000

type Entry = { n: number; total: number; last: number; max: number; recent: Array<[at: number, ms: number]> }

export type PerfRow = {
  name: string
  /** Runs since the mod loaded. */
  n: number
  /** Runs in the last minute. */
  perMin: number
  /** Milliseconds per run, on average; 0 for counts. */
  avgMs: number
  lastMs: number
  maxMs: number
  /** Milliseconds spent in the last minute. */
  busyMs: number
}

export type PerfSnapshot = { sinceMs: number; rows: PerfRow[] }

export const createPerf = () => {
  const entries = new Map<string, Entry>()
  const loadedAt = Date.now()

  const record = (name: string, ms: number) => {
    const e = entries.get(name) ?? { n: 0, total: 0, last: 0, max: 0, recent: [] }
    const at = Date.now()
    e.n++
    e.total += ms
    e.last = ms
    e.max = Math.max(e.max, ms)
    e.recent.push([at, ms])
    // Keep only the window, so a long session doesn't grow this.
    while (e.recent.length && at - e.recent[0]![0] > WINDOW) e.recent.shift()
    entries.set(name, e)
  }

  /** Starts timing `name`; call what it returns when it's done. */
  const start = (name: string) => {
    const t0 = now()
    return () => record(name, now() - t0)
  }

  /** Times `fn`, sync or async, under `name`. */
  const time = <T>(name: string, fn: () => T): T => {
    const done = start(name)
    let out: T
    try {
      out = fn()
    } catch (err) {
      done()
      throw err
    }
    if (out instanceof Promise) return out.finally(done) as T
    done()
    return out
  }

  /** Counts one occurrence of `name`, with no time. */
  const count = (name: string) => record(name, 0)

  const snapshot = (): PerfSnapshot => {
    const at = Date.now()
    const rows = [...entries].map(([name, e]) => {
      const recent = e.recent.filter(([t]) => at - t <= WINDOW)
      return {
        name,
        n: e.n,
        perMin: recent.length,
        avgMs: e.n ? e.total / e.n : 0,
        lastMs: e.last,
        maxMs: e.max,
        busyMs: recent.reduce((s, [, ms]) => s + ms, 0),
      }
    })
    // What cost the most in the last minute first, then what ran most.
    rows.sort((a, b) => b.busyMs - a.busyMs || b.perMin - a.perMin)
    return { sinceMs: at - loadedAt, rows }
  }

  return { start, time, count, snapshot }
}

export type Perf = ReturnType<typeof createPerf>

/** Milliseconds, short: 0.4ms, 12ms, 1.2s. */
export const ms = (v: number): string => (v >= 1_000 ? `${(v / 1_000).toFixed(1)}s` : v >= 10 ? `${Math.round(v)}ms` : `${v.toFixed(1)}ms`)

